from author import *
c=C('TCP可靠传输与流量控制')
S(c,'序号与确认机制',[T('序号','TCP 把字节流逐个编号，序号字段填本报文段第一个字节的编号'),T('确认号','确认号是期望收到的下一个字节编号，收到 1 到 2000 就回 2001'),T('累积确认','确认号之前的字节都已收到，一次确认能覆盖好几个报文段')],[P('先看一个具体场景。发送方把要发的数据看成一串连续的字节，从第一个字节开始编号。假设每段带 1000 个字节，第一段的序号是 1，第二段是 1001，第三段是 2001。接收方按编号拼回去，再回一个确认，告诉发送方下一步想收哪个字节。',[1,2],['先按字节编号','序号不是报文段编号']),P('确认号填的是期望收到的下一个字节编号。前面 2000 个字节都到了，接收方就回 2001，而不是回 2000。一次确认覆盖多个报文段的做法叫累积确认，中间某段丢了，后面的确认会重复同一个编号。这里有个常考点：序号和确认号都按字节编号，不是按段数编号。',[3],['确认号指向下一个字节','累积确认能覆盖多段'])],['序号与确认'])

S(c,'超时重传与 RTT 估计',[T('RTO','重传超时时间，发出后超过这段时间还没收到确认就重发'),T('加权平均','平滑往返时间和偏差一起决定 RTO，公式是 RTTs 加四倍 RTTd'),T('退避','超时后把 RTO 翻倍，连续超时就一次次把间隔拉长')],[P('再看丢包怎么办。发送方每发出一段就启动一个计时器，时间到了还没收到确认，就认为这一段可能丢了，于是重发一遍，这叫超时重传。计时器的时长叫 RTO。RTO 定得太短，确认还在路上就重发，白白浪费带宽；定得太长，丢包要等很久才补上，传输就慢。',[1],['计时器到期就重发','RTO 不能乱定']),P('所以 RTO 要根据往返时间动态估计。做法是先算平滑值 RTTs，再算偏差 RTTd，最后用 RTTs 加四倍 RTTd 得到 RTO。超时后通常把 RTO 翻倍，这叫退避，避免网络已经堵了还不停重发。超时重传要等计时器到期，快重传靠重复确认触发，不用等。',[2,3],['RTO 按往返时间估计','超时后要退避'])],['超时重传','RTT 估计'])

S(c,'滑动窗口',[T('窗口范围','窗口大小是 4000 字节，允许连续发出、还没被确认的数据量'),T('已发未确认','已经发出还没确认的段仍然占着窗口，不能再发新的'),T('窗口滑动','收到确认后左边界右移，空出来的位置才能发新段')],[P('仍用刚才的例子。窗口大小是 4000 字节，每段 1000 字节，窗口里最多装四段。发送方先把 1、1001、2001、3001 四段连续发出去，这时窗口左边界是 1，右边界是 4000。四段都在等确认，窗口被占满，暂时不能再发新数据。',[1,2],['窗口大小决定在途数据量','已发未确认的段占窗口'],phase='send',anchor='窗口大小是 4000 字节'),P('现在收到确认号 2001，表示 1 到 2000 字节已经收下，窗口左边界移到 2001，右边界移到 6000。此时 2001 和 3001 已发出未确认，占着窗口，可以新发 4001 和 5001 两段。窗口跟着确认号向右滑动，这就是滑动窗口名字的来历。',[3],['窗口随确认号右移','空出的位置才能补发'],phase='ack',anchor='窗口跟着确认号向右滑动')],['滑动窗口'],visual=G('window'))

S(c,'流量控制',[T('接收窗口','接收方按自己缓存的剩余量通告窗口，告诉对方还能收多少'),T('零窗口','缓存满了就通告零，发送方暂停发送，只发探测报文'),T('窗口探测','零窗口后发送方定时发探测，等接收方腾出空间再恢复')],[P('再看更现实的约束。接收方缓存不是无限的，处理速度也有限。它每次回确认时，会顺带告诉发送方自己还能接收多少字节，这个值叫接收窗口。发送方必须照这个数限制自己，让已发未确认的数据不超过它。接收方通告 2000 字节，发送方最多让两段数据同时在路上。',[1],['接收窗口由接收方通告','发送量不能超过它']),P('如果接收方缓存满了，就通告零窗口，发送方暂停发送，但会定时发窗口探测报文，等接收方腾出空间再继续。这里要和拥塞控制分清楚：流量控制看接收方缓存，窗口由接收方通告；拥塞控制看整个网络，由发送方根据丢包调整。两个窗口都限制发送，实际取较小的那个。',[2,3],['零窗口要发探测','流量控制不等于拥塞控制'])],['流量控制','接收窗口'])

S(c,'窗口计算例题',[T('题设','MSS 等于 1000 字节，发送窗口是 4000 字节，已发 1 到 3001 四段'),T('可再发几段','收到确认号 2001，窗口滑动后还能新发几段'),T('窗口位置','左边界取确认号，右边界等于左边界加窗口大小再减一')],[P('做一道窗口计算题。设 MSS 等于 1000 字节，发送窗口是 4000 字节，发送方已经连续发出 1、1001、2001、3001 四段，现在收到确认号 2001 的确认。按刚才的步骤，先把四段摆进窗口，再看确认号把左边界推到哪，最后算右边界和新段。',[1],['先把已发四段摆进窗口','确认号决定左边界']),P('步骤是这样的：左边界取确认号 2001，右边界等于 2001 加 4000 再减 1，得到 6000。窗口里能放 2001、3001、4001、5001 四段，其中前两段已经发过，所以只能新发 4001 和 5001。检查方法：先定左边界，再算右边界。',[2,3],['窗口范围 2001 到 6000','可新发 4001 和 5001'])],['窗口计算','确认号'])

S(c,'停止等待与滑动窗口对比',[T('效率','停止等待一次只发一段，等确认时链路闲着'),T('流水线','滑动窗口允许连发多段，像流水线一样填满链路'),T('信道利用率','利用率取决于窗口能否盖住一个往返时间内的发送量')],[P('最后对比两种可靠传输的做法。最早的办法叫停止等待，发一段，等确认到了再发下一段，最稳妥，但等确认时链路是空的。假设发送时延 1 毫秒、往返时间 20 毫秒，链路利用率大约只有百分之五，大部分时间在空转，很不划算。',[1],['停止等待太浪费链路','利用率只有百分之五']),P('滑动窗口的思路是把等待时间用起来：窗口里有多段就能连续发送，确认回来一段就补发一段，像流水线一样。窗口越大，能盖住的往返时间越长，利用率越高，但窗口受接收窗口和拥塞窗口两头限制，不是想开多大就开多大。检查利用率时，先算一个往返时间能发多少数据。',[2,3],['窗口把等待时间用起来','窗口受两头限制'])],['可靠传输','信道利用率'])

S(c,'窗口与流量控制练习',[T('题设','MSS 等于 1000 字节，发送窗口 4000 字节，已发 1、1001、2001、3001'),T('第一问','收到确认号 2001 后，还能新发哪两个报文段'),T('第二问','接收窗口是 2000 字节时，发送窗口的上限是多少')],[P('暂停一下，用窗口计算做两个小题。第一，MSS 等于 1000 字节，窗口是 4000 字节，已发出 1、1001、2001、3001 四段，收到确认号 2001 后还能新发哪两段。第二，接收窗口是 2000 字节时，发送窗口上限是多少。先自己判断，再翻到下一页对照。',[1,2,3],['先定窗口左边界','再比较两个窗口'])],['窗口练习'],kind='question')

S(c,'窗口与流量控制练习答案',[T('第一问','窗口移到 2001 到 6000，可新发 4001 和 5001 两段'),T('第二问','发送窗口不超过 2000 字节，取拥塞窗口和接收窗口的较小值'),T('检查方法','先定左边界，再算右边界，最后数已发未确认的段')],[P('第一问：确认号 2001 表示前 2000 字节已确认，左边界移到 2001，右边界是 2001 加 4000 再减 1，等于 6000，所以新发 4001 和 5001 两段。第二问：接收窗口 2000 字节，发送窗口不超过它，实际取两个窗口的较小值。检查时先定左边界，再算右边界。',[1,2,3],['先定左边界','再算右边界'])],['窗口练习'],kind='answer')

c=C('TCP拥塞控制')
S(c,'拥塞控制与流量控制的区别',[T('控制对象','流量控制管接收方缓存，拥塞控制管整个网络的承载能力'),T('判断依据','流量控制看接收窗口，拥塞控制看丢包和往返时间的变化'),T('结果','流量控制限制发送量，拥塞控制调整拥塞窗口和发送速率')],[P('先分清两个容易混的概念。假设接收方缓存还很空，可中间链路和路由器已经排长队，分组开始被丢弃，这时只盯着接收窗口就不够了。网络本身也会堵，拥塞控制就是让发送方根据网络拥堵程度调整发送量，避免把更多分组塞进堵住的链路。',[1],['网络本身也会堵','不能只看接收方']),P('流量控制和拥塞控制管的对象不同。流量控制看接收方，依据是接收方通告的接收窗口，怕把接收方缓存撑爆；拥塞控制看网络，依据是超时和重复确认这类丢包信号，靠调整拥塞窗口改变速率。发送窗口取两者中较小的那个，两个机制是配合，不是替代，两者要一起看。',[2,3],['流量控制看接收方','拥塞控制看网络'])],['拥塞控制','概念辨析'])

S(c,'慢启动与拥塞避免',[T('cwnd','拥塞窗口是发送方自己维护的窗口，用来估计网络还能承受多少数据'),T('慢启动','从 1 个 MSS 开始，每个往返时间翻倍，按 1、2、4、8、16 增长'),T('拥塞避免','到达慢启动门限后每轮只加 1，从 16 之后变成 17、18、19')],[P('先看拥塞窗口怎么长大。发送方维护一个拥塞窗口，慢启动阶段从 1 个 MSS 开始，每收到一个确认就加一个 MSS，于是一个往返时间里窗口翻一倍，依次是 1、2、4、8、16。它增长看起来不慢，是因为起点很低，所以这个阶段叫慢启动。',[1,2],['初值只有 1 个 MSS','每轮翻倍增长'],phase='slow',anchor='慢启动阶段从 1 个 MSS 开始'),P('窗口不能一直翻倍。发送方设一个慢启动门限，这里等于 16，到达慢启动门限就换成线性增长，每轮只加 1，从 16 之后变成 17、18、19，这一段叫拥塞避免。慢启动是指数增长，拥塞避免是线性增长，越过门限才进入下一阶段。',[3],['慢启动指数增长','拥塞避免线性增长'],phase='recover',anchor='到达慢启动门限就换成线性增长')],['慢启动','拥塞避免'],visual=G('congestion'))

S(c,'快重传与快恢复',[T('三个重复 ACK','接收方收到失序段就重复确认同一个编号，连发三次'),T('快重传','发送方收到三个重复确认，立即重发丢失的那一段，不等超时'),T('快恢复','门限设为当前窗口的一半，窗口降到门限，直接进入拥塞避免')],[P('再看一种更常见的情况。某一段在网络里丢了，后面几段却到了，接收方每收到一个失序段，就重复回同一个确认号，意思是这里还缺一段。发送方连着收到三个重复确认，就知道不是偶发的乱序，而是真丢了，可以马上重传，不必等到计时器超时。',[1],['失序段会触发重复确认','三个重复确认说明真丢了']),P('这套动作叫快重传加快恢复。快重传是立刻重发丢失段；快恢复是把慢启动门限减半，窗口降到门限，然后直接进入拥塞避免，不必回到 1。对比一下：超时说明情况更严重，窗口打回 1 重新慢启动；三个重复确认只减半，两者触发条件不同，不要混用。',[2,3],['快重传不等计时器','快恢复只减半不回 1'])],['快重传','快恢复'])

S(c,'拥塞窗口计算例题',[T('题设','拥塞窗口初值 1 个 MSS，慢启动门限 ssthresh 等于 16'),T('轮次变化','1、2、4、8、16，之后拥塞避免每轮加 1：17、18、19'),T('超时后','窗口 24 时超时，门限减半为 12，窗口回到 1 重新慢启动')],[P('做一道经典计算题。拥塞窗口初值是 1 个 MSS，慢启动门限 ssthresh 等于 16。慢启动每个往返时间翻一倍，依次是 1、2、4、8、16；到了 16 就转入拥塞避免，之后每轮加 1，变成 17、18、19。这里每一行对应一个往返时间，数窗口时要一轮一轮数。',[1,2],['先翻倍到门限','越过门限变线性']),P('再看超时。如果窗口涨到 24 个 MSS 时发生超时，说明网络严重拥塞，处理办法是门限减半，24 的一半是 12，所以 ssthresh 变成 12，拥塞窗口回到 1，重新慢启动；这次慢启动到 8 之后，下一次涨到 12 就进入拥塞避免。检查办法：超时先减半再回到 1。',[3],['超时门限减半为 12','窗口回到 1 重新慢启动'])],['拥塞窗口计算','超时处理'])

S(c,'发送窗口与吞吐',[T('min(cwnd,rwnd)','实际发送窗口取拥塞窗口和接收窗口的较小值'),T('瓶颈','吞吐量受瓶颈链路带宽和窗口大小共同限制'),T('时延影响','往返时间越大，同样窗口能跑出的吞吐越低')],[P('现在把两个窗口合起来看。实际能发多少，取拥塞窗口和接收窗口里较小的那个，写成 min(cwnd,rwnd)。网络通畅但接收方缓存小，就被接收窗口卡住；接收方缓存大但链路拥堵，就被拥塞窗口卡住。发送方按较小值安排发送，不会自己加码。',[1],['取两个窗口的较小值','谁小就被谁卡住']),P('吞吐量还和时延有关。一个窗口的数据送出去再等确认回来，需要一个往返时间，所以粗略的吞吐等于窗口大小除以往返时间。窗口是 4000 字节、往返时间 20 毫秒时，每秒大约发 200 千字节。瓶颈链路带宽是上限，窗口和时延决定能不能跑满。',[2,3],['吞吐约等于窗口除以往返时间','带宽是上限'])],['发送窗口','吞吐量'])

S(c,'易错点汇总',[T('超时与重复 ACK','超时窗口回到 1，三个重复 ACK 只把窗口降到一半'),T('初值','拥塞窗口初值 1 个 MSS，门限一般由题目直接给出'),T('回合计算','一个往返时间算一轮，指数增长只属于慢启动阶段')],[P('把这一章的易错点集中说一下。第一，看触发信号：超时说明情况严重，窗口回到 1 重新慢启动；收到三个重复确认触发快重传，窗口只降到门限，直接进入拥塞避免。第二，看初始值：拥塞窗口从 1 个 MSS 开始，慢启动门限一般由题目给定。',[1,2],['超时回 1，重复 ACK 减半','初值 1 个 MSS']),P('第三，看回合怎么数。一个往返时间算一轮，慢启动窗口翻倍，拥塞避免窗口加 1，两个阶段不能混着算。还有一点，慢启动不是慢慢启动，意思是起点小、增长快。做计算题时先画表格，把轮次、窗口、门限三列写清楚，再套规则，先看阶段再代数。',[3],['一轮就是一个往返时间','先画表再套规则'])],['易错点','计算规范'])

S(c,'拥塞控制练习',[T('题设','拥塞窗口初值 1 个 MSS，慢启动门限等于 16'),T('第一问','写出慢启动各轮的窗口，说明何时转入拥塞避免'),T('第二问','窗口等于 24 时发生超时，新门限和新窗口是多少')],[P('暂停一下，做两个拥塞控制小题。第一，拥塞窗口初值 1 个 MSS，慢启动门限等于 16，写出慢启动每一轮的窗口大小，并说明什么时候转入拥塞避免。第二，窗口涨到 24 个 MSS 时发生超时，新的门限和窗口分别是多少。请写出过程，再翻到下一页对照。',[1,2,3],['先按轮次翻倍','再看超时后怎么复位'])],['拥塞练习'],kind='question')

S(c,'拥塞控制练习答案',[T('第一问','1、2、4、8、16，到 16 后转拥塞避免，变成 17、18、19'),T('第二问','门限减半为 12，窗口回到 1，重新慢启动'),T('检查方法','先判断阶段，再套指数或线性规则')],[P('第一问：慢启动每轮翻倍，依次是 1、2、4、8、16，到门限 16 后转拥塞避免，此后每轮加 1，变成 17、18、19。第二问：超时后门限取当前窗口的一半，24 的一半是 12，所以 ssthresh 等于 12，窗口回到 1，重新慢启动。检查方法：先看触发信号，再判断该翻倍还是加 1。',[1,2,3],['先看阶段再套规则','超时回 1'])],['拥塞练习'],kind='answer')

c=C('应用层与综合复习')
S(c,'DNS 域名解析',[T('域名层次','域名从右往左分层，根、顶级域、二级域逐级细分'),T('递归与迭代','主机把查询交给本地服务器，本地服务器再逐级去问'),T('缓存','解析结果按生存时间缓存，下次先查缓存再发查询')],[P('先看浏览器里输入网址之后发生了什么。域名从右往左分层，最右边是顶级域，中间是学校的二级域。主机不会一级一级去问，它把查询交给本地域名服务器。本地服务器先查缓存，没有就向根域名服务器开始逐级向下问，先找顶级域，再找权威服务器。',[1],['域名从右往左分层','本地服务器代查'],phase='dns',anchor='向根域名服务器开始逐级向下问'),P('拿到 IP 地址后浏览器才发 HTTP 请求，所以域名解析是访问网页的第一步。解析结果会按生存时间缓存，时间没到就先用缓存，省掉一次查询。这里有两个术语：主机把活全交给本地服务器，叫递归查询；本地服务器逐级去问，叫迭代查询，不要写反。',[2,3],['解析结果会缓存','递归与迭代要分清'],phase='http',anchor='拿到 IP 地址后浏览器才发 HTTP 请求')],['DNS','域名解析'],visual=G('dnsflow'))

S(c,'HTTP 与 HTTPS',[T('请求响应','浏览器发请求行和首部，服务器回状态码和网页内容'),T('持久连接','一个 TCP 连接上可以连续发多个请求，减少握手开销'),T('TLS 加密','HTTPS 在 HTTP 下面加一层 TLS，端口从 80 变成 443')],[P('解析完域名，浏览器和服务器建立 TCP 连接，然后在上面发 HTTP 请求。请求里有方法、路径和首部，服务器回状态码和网页内容。HTTP 是无状态的，请求独立处理。早期每个请求都新建连接，后来用持久连接，一个连接上可以连续发多个请求，省掉反复握手。',[1,2],['请求和响应成对出现','持久连接省握手']),P('HTTP 的内容是明文传的，中间节点能看到，于是有了 HTTPS。HTTPS 等于 HTTP 加上 TLS，端口从 80 变成 443，多了一层加密。它多了一次 TLS 握手，用来协商密钥、验证服务器身份。易错点：HTTPS 不是新协议，是 HTTP 套上安全层。',[3],['HTTPS 等于 HTTP 加 TLS','多了 TLS 握手'])],['HTTP','HTTPS'])

S(c,'访问一个网页的完整过程',[T('DNS 查询','先把域名换成 IP 地址，可能要经过缓存和多次查询'),T('TCP 握手','和服务器建立连接，三次握手用掉一个往返时间'),T('请求与响应','发 HTTP 请求，收到响应后浏览器解析并加载资源')],[P('把访问网页的过程完整走一遍。输入网址后，浏览器先查缓存，没有就让本地域名服务器把域名解析成 IP 地址。拿到 IP 后，浏览器和服务器建立 TCP 连接，完成三次握手；如果是 HTTPS，还要再做 TLS 握手。连接建好，才发送 HTTP 请求。',[1,2],['先解析域名再握手','HTTPS 多一次 TLS 握手']),P('响应回来后，浏览器解析网页，遇到图片、样式和脚本，还要再对相应的服务器发请求，每个新资源都可能重复解析和请求。打开一个网页的耗时，往往是多次往返叠加的结果。易错点：域名解析在 TCP 握手之前，TLS 握手在 TCP 握手之后。',[3],['资源要分别请求','顺序不要写反'])],['网页访问','完整流程'])

S(c,'DHCP、FTP 与邮件协议',[T('DHCP 四步','发现、提供、请求、确认，自动拿到 IP 地址和网关'),T('FTP 双连接','控制连接用 21 端口，数据连接用 20 端口，命令和数据分开'),T('SMTP 与 POP3','SMTP 用 25 端口发邮件，POP3 用 110 端口把邮件收回来')],[P('再串几个常考协议。新电脑接入网络时，先由 DHCP 自动分配地址，过程分四步：发现、提供、请求、确认，服务器把 IP 地址、网关和域名服务器一起交给主机。文件传输用 FTP，它开两条连接，控制连接走 21 端口，数据连接走 20 端口。',[1,2],['DHCP 四步拿地址','FTP 控制和数据分开']),P('电子邮件也有分工。发邮件用 SMTP，端口 25，负责把邮件从客户端推到服务器；收邮件用 POP3，端口 110，把邮件取回本地。容易错的是以为 SMTP 能发也能收，其实收信要靠 POP3 或 IMAP。记忆时把协议和端口成对记。',[3],['发信 SMTP，收信 POP3','协议和端口成对记'])],['DHCP','FTP 与邮件'])

S(c,'综合时延例题',[T('题设','RTT 等于 20 毫秒，解析、握手、请求响应各占一个 RTT'),T('三倍 RTT','三段过程串行相加，总时间等于 3 个往返时间'),T('结果','20 乘 3 等于 60 毫秒，这是理想情况下的首字节时间')],[P('做一道综合时延题。设往返时间 RTT 等于 20 毫秒，域名解析用 1 个 RTT，TCP 握手用 1 个 RTT，HTTP 请求响应再用 1 个 RTT，三段串起来就是 3 个 RTT，也就是 60 毫秒。这是从输入网址到看到首字节的理想时间。',[1,2],['三段串行相加','3 乘 20 得 60 毫秒']),P('算这类题要写清假设：缓存为空，没有排队和重传。如果缓存里有解析结果，DNS 那个 RTT 就能省掉；如果是 HTTPS，还要加 TLS 握手。检查时画时间轴，把每次往返标出来，数一共几个 RTT，再乘数值，别漏别重复。',[3],['先写清假设','画时间轴数往返'])],['综合时延','计算例题'])

S(c,'复习与答题策略',[T('分层主线','物理传比特、链路传帧、网络传分组、传输传报文段'),T('计算清单','时延、子网划分、分片、最长前缀匹配、序号窗口、拥塞窗口'),T('易错点','流量控制与拥塞控制、超时重传与快重传、慢启动与拥塞避免')],[P('最后把整门课的主线收一收。学网络最有效的方法是抓住分层：物理层把比特变成信号，链路层把帧送过一段链路，网络层用 IP 地址把分组送到目的地，传输层用端口把数据交给进程，应用层处理具体业务。出了故障先想是哪一层的事，这个顺序要记牢。',[1],['抓分层这条主线','每层解决一类问题']),P('考试常见的计算就几类：时延、子网划分、IP 分片、最长前缀匹配、TCP 序号与窗口、拥塞窗口。答题时先写公式或规则，再代数字，最后写检查方法。容易混的成对概念要专门记：流量控制和拥塞控制、超时重传和快重传、慢启动和拥塞避免。',[2,3],['计算题写公式再代数字','成对概念专门记'])],['复习策略','计算清单'])

S(c,'应用层与综合练习',[T('题设','RTT 等于 20 毫秒，解析、握手、请求响应各占一个 RTT'),T('第一问','首字节时间大约是多少，写出计算过程'),T('第二问','HTTPS 在 HTTP 基础上多了什么')],[P('暂停一下，做最后两个小题。第一，往返时间 RTT 等于 20 毫秒，域名解析、TCP 握手、HTTP 请求和响应各用 1 个 RTT，首字节时间大约是多少。第二，HTTPS 在 HTTP 基础上多了什么。请写出答案和依据，注意先假设缓存为空，再翻到下一页对照。',[1,2,3],['先数有几个往返','再看有没有缓存'])],['综合练习'],kind='question')

S(c,'应用层与综合练习答案',[T('第一问','3 个 RTT 相加，20 乘 3 等于 60 毫秒'),T('第二问','多了 TLS 握手和加密传输，端口从 80 变成 443'),T('检查方法','先数往返次数，再看有没有缓存和额外资源')],[P('第一问：DNS 解析、TCP 握手、HTTP 请求响应各 1 个 RTT，20 毫秒乘 3 等于 60 毫秒，前提是缓存为空、无排队无重传。第二问：HTTPS 等于 HTTP 加 TLS，多了 TLS 握手和加密，端口从 80 变成 443。检查方法：先数往返次数，再乘 RTT。',[1,2,3],['先数往返次数','答计算题写清假设'])],['综合练习'],kind='answer')
